mapper.sql:
SELECT parent_run_id,parent_action_id,parent_attempt_id,child_run_id,origin_kind
  FROM public.agent_runtime_execution_child_runs WHERE tenant_id=#{tenant}
UNION
SELECT parent_run_id,parent_action_id,parent_attempt_id,child_run_id,'PROGRAM' AS origin_kind
  FROM public.agent_runtime_execution_program_child_runs WHERE tenant_id=#{tenant}
UNION
SELECT parent_run_id,NULL::varchar AS parent_action_id,NULL::text AS parent_attempt_id,child_run_id,'PLAN' AS origin_kind
  FROM public.agent_runtime_execution_plan_child_runs WHERE tenant_id=#{tenant}

mapper.select:
SELECT parent_run_id,parent_action_id,parent_attempt_id,child_run_id,origin_kind FROM () edge
 WHERE parent_run_id IN #{run}
   AND child_run_id IN #{run}
 ORDER BY parent_run_id,parent_action_id NULLS FIRST,parent_attempt_id,child_run_id
